verus! {

    /// Implementation of `greater`: given two equally‐sized vectors of i8,
    /// returns a vector of bools where each entry indicates whether
    /// the corresponding entry of `a` (as i32) is strictly greater than
    /// that of `b` (as i32).
    fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool>
        requires
            a.len() == b.len(),
        ensures
            |res: &Vec<bool>| 
                res.len() == a.len()
             && forall(|i: usize| i < a.len()
                          ==> res[i] == (i32::from(a[i]) > i32::from(b[i]))),
    {
        // Allocate result with the same capacity as `a.len()`.
        let mut res: Vec<bool> = Vec::with_capacity(a.len());
        let mut i: usize = 0;
        // Loop over all indices
        while i < a.len() {
            // Loop invariants
            invariant(i <= a.len());
            invariant(res.len() == i);
            invariant(forall(|j: usize| j < i
                              ==> res[j] == (i32::from(a[j]) > i32::from(b[j]))));
            // Show that i strictly decreases the measure a.len() - i
            decreases a.len() - i;

            // Push the comparison of the i-th elements
            res.push(i32::from(a[i]) > i32::from(b[i]));
            i += 1;
        }
        res
    }

}